11	
12	const keyringService = "entire-cli"
13	
14	// Store manages CLI authentication tokens in the OS keyring.
15	type Store struct {
16		service string
17	}
18	
19	// NewStore returns a Store backed by the system keyring.
20	func NewStore() *Store {
21		return &Store{service: keyringService}
22	}
23	
24	// NewStoreWithService returns a Store with a custom keyring service name (for testing).
25	func NewStoreWithService(service string) *Store {
26		return &Store{service: service}
27	}
28	
29	// SaveToken persists an access token for the given base URL.
30	func (s *Store) SaveToken(baseURL, token string) error {
31		token = strings.TrimSpace(token)
32		if token == "" {
33			return errors.New("refusing to save empty token")
34		}
35	
36		if err := keyring.Set(s.service, baseURL, token); err != nil {
37			return fmt.Errorf("save token to keyring: %w", err)
38		}
39	
40		return nil
41	}
42	
43	// GetToken retrieves a stored token for the given base URL.
44	// Returns an empty string (and no error) if no token is stored.
45	func (s *Store) GetToken(baseURL string) (string, error) {
46		token, err := keyring.Get(s.service, baseURL)
47		if errors.Is(err, keyring.ErrNotFound) {
48			return "", nil
49		}
50		if err != nil {
51			return "", fmt.Errorf("get token from keyring: %w", err)
52		}
53	
54		return token, nil
55	}
56	
57	// DeleteToken removes a stored token for the given base URL.
58	func (s *Store) DeleteToken(baseURL string) error {
59		err := keyring.Delete(s.service, baseURL)
60		if errors.Is(err, keyring.ErrNotFound) {
61			return nil
62		}
63		if err != nil {
64			return fmt.Errorf("delete token from keyring: %w", err)
65		}
66	
67		return nil
68	}
69	
70	// LookupCurrentToken retrieves the token for the current base URL.
71	func LookupCurrentToken() (string, error) {
72		store := NewStore()
73		return store.GetToken(api.BaseURL())
74	}
