14	)
15	
16	const (
17		maxResponseBytes = 1 << 20
18		clientID         = "entire-cli"
19	)
20	
21	type Client struct {
22		httpClient *http.Client
23		baseURL    string
24	}
25	
26	type DeviceAuthStart struct {
27		DeviceCode              string `json:"device_code"`
28		UserCode                string `json:"user_code"`
29		VerificationURI         string `json:"verification_uri"`
30		VerificationURIComplete string `json:"verification_uri_complete"`
31		ExpiresIn               int    `json:"expires_in"`
32		Interval                int    `json:"interval"`
33	}
