// ErrorResponse represents a standard API error response.
type ErrorResponse struct {
	Error string `json:"error"`
}

// APIError is returned by CheckResponse for non-2xx responses. Callers can use
// errors.As to inspect the HTTP status, or IsAPIErrorStatus for a quick check.
type APIError struct {
	StatusCode int
	Message    string
}

func (e *APIError) Error() string {
	if e.Message != "" {
		return fmt.Sprintf("API error: %s (status %d)", e.Message, e.StatusCode)
	}
	return fmt.Sprintf("API error: status %d", e.StatusCode)
}

// IsAPIErrorStatus reports whether err wraps an *APIError with the given HTTP status.
func IsAPIErrorStatus(err error, status int) bool {
	var ae *APIError
	return errors.As(err, &ae) && ae.StatusCode == status
}

// CheckResponse returns an error if the response status code indicates failure.
// For non-2xx responses, it reads and parses the error message from the body
// and returns it as an *APIError. The caller is responsible for closing resp.Body.
func CheckResponse(resp *http.Response) error {
	if resp.StatusCode >= 200 && resp.StatusCode < 300 {
		return nil
	}

	apiError := &APIError{StatusCode: resp.StatusCode}

	body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
	if err != nil {
		return apiError
	}

	var parsed ErrorResponse
	if err := json.Unmarshal(body, &parsed); err == nil && strings.TrimSpace(parsed.Error) != "" {
		apiError.Message = parsed.Error
		return apiError
	}

	if text := strings.TrimSpace(string(body)); text != "" {
		apiError.Message = text
	}
	return apiError
}

