113	func runAuthList(ctx context.Context, w io.Writer, store authStatusStore, list authTokenLister, baseURL string, jsonOut bool) error {
114		token, err := store.GetToken(baseURL)
115		if err != nil {
116			return fmt.Errorf("read keychain: %w", err)
117		}
118		if token == "" {
119			return fmt.Errorf("not logged in to %s; run 'entire login' first", baseURL)
120		}
121	
122		tokens, err := list(ctx, token)
123		if err != nil {
124			return err
125		}
126	
127		if jsonOut {
128			enc := json.NewEncoder(w)
129			enc.SetIndent("", "  ")
130			if err := enc.Encode(tokens); err != nil {
131				return fmt.Errorf("encode JSON: %w", err)
132			}
133			return nil
134		}
135	
136		if len(tokens) == 0 {
137			fmt.Fprintln(w, "No active tokens.")
138			return nil
139		}
140	
141		// Stable order: most recently used first, then created.
142		sort.Slice(tokens, func(i, j int) bool {
143			li := lastUsedSortKey(tokens[i])
144			lj := lastUsedSortKey(tokens[j])
145			if li != lj {
146				return li > lj
147			}
148			return tokens[i].CreatedAt > tokens[j].CreatedAt
149		})
150	
151		tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
152		fmt.Fprintln(tw, "ID\tNAME\tSCOPE\tCREATED\tLAST USED\tEXPIRES")
153		for _, t := range tokens {
154			fmt.Fprintf(tw, "%s\t%s\t%s\t%s\t%s\t%s\n",
155				t.ID,
156				fallback(t.Name, "-"),
157				fallback(t.Scope, "-"),
158				formatDate(t.CreatedAt),
159				formatLastUsed(t.LastUsedAt),
160				formatDate(t.ExpiresAt),
161			)
162		}
163		return tw.Flush() //nolint:wrapcheck // tabwriter flush error is rare and self-explanatory
164	}
